from pathlib import Path
import json,html,re
from build_pages import header,footer
ROOT=Path(__file__).resolve().parent.parent;PUB=ROOT/'public';catalog={'brand':'MONTE WO Strength Index™','message':'MEASURE. PROVE. EARN. CLIMB.','disciplines':json.loads((ROOT/'content/strength/disciplines.json').read_text())};catalog['rulebooks']=[json.loads((ROOT/'content/strength'/(d['rulebookId']+'.json')).read_text()) for d in catalog['disciplines']];catalog['models']=[json.loads((ROOT/'content/strength'/(d['modelId']+'.json')).read_text()) for d in catalog['disciplines']];(PUB/'strength-catalog.json').write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n');ranks=json.loads((PUB/'ranks.json').read_text());esc=lambda x:html.escape(str(x),quote=True)
brand='<span class="index-brand">MEASURE. PROVE. EARN. CLIMB.</span>'
notice='<div class="draft-note"><b>DRAFT — NOT OFFICIAL</b>All four launch methodologies and threshold tables await independent approval. No official rank, MONTE Verified award or MONTE Climb Scale percentage can be earned from these drafts. The former 1–1000 demo is retired.</div>'
links='<div class="strength-links"><a href="/strength/">Discipline ranks ↗</a><a href="/methodology/">Methodology &amp; MONTE Standard ↗</a><a href="/exercises/">Train without ranking ↗</a></div>'
gallery='<div class="rank-gallery">'+''.join(f'<div><img class="rank-emblem" src="{r["icon"]}" alt="{esc(r["name"])} rank emblem" width="288" height="288"><b>{esc(r["name"])}</b><small>RANK {i+1:02}</small></div>' for i,r in enumerate(ranks))+'</div>'
hero=f'<section class="strength-hero">{brand}<h1>Four disciplines.<br><em>Every rank earned.</em></h1><p>MONTE WO Strength Index™ · Managed by VitaFlex Business Group.<br>LEVE. KLASE. MONTE WO. — LIFT. RANK. CLIMB HIGH.</p>{notice}{links}</section>'
cards='<section class="discipline-grid" id="discipline-cards" aria-label="Independent discipline ranks">'+''.join(f'<article class="discipline-card"><div class="discipline-top"><span>DISCIPLINE 0{i+1}</span><span>DRAFT — NOT OFFICIAL</span></div><h2>{d["name"]}</h2><div class="unranked-mark">—</div><h3>No official rank</h3><p>Qualifying standards await approval. Your workouts, streaks and time in the app cannot grant a rank.</p><a href="/methodology/#{d["id"]}">Read the draft MONTE Standard ↗</a><small class="model-id">{d["modelId"]} · No official progress percentage</small></article>' for i,d in enumerate(catalog['disciplines']))+'</section>'
profile='''<form id="profile-form"><h3>1. Ranking profile</h3><div class="strength-form-grid"><label>Bodyweight<input name="bodyweight" type="number" min="30" max="772" step="0.001" required></label><label>Bodyweight unit<select name="unit"><option>kg</option><option>lb</option></select></label><label>Age at performance (18–100)<input name="ageYears" type="number" min="18" max="100" step="1" required></label><label>Reference category<select name="sexCategory"><option value="unclassified">Unclassified / not specified</option><option value="female">Female reference</option><option value="male">Male reference</option></select></label></div><label>Reason for this profile revision<input name="reason" maxlength="1000" value="Initial ranking profile" required></label><p>Category support depends on approved evidence; unsupported categories are not extrapolated. Software input limits are not validated ranking populations. A profile change keeps historical results and adds non-awarding scenarios.</p><button class="button" type="submit">Save profile revision</button></form>'''
performance='''<form id="performance-form"><h3>2. Submit a performance</h3><div class="strength-form-grid"><label>Discipline<select id="performance-discipline" name="discipline">'''+''.join(f'<option value="{d["id"]}">{d["name"]}</option>' for d in catalog['disciplines'])+'''</select></label><label>Load, including bar and plates<input name="load" type="number" step="0.001" min="0.001" max="2204" required></label><label>Load unit<select name="unit"><option>kg</option><option>lb</option></select></label><label>Completed repetitions<input name="reps" type="number" min="1" max="10" step="1" value="1" required></label><label>Performance date<input name="performedOn" type="date" required></label><label>Result type<select name="resultType"><option value="tested">Tested single (not necessarily a true maximum)</option><option value="estimated">Estimated 1RM from multiple reps</option></select></label></div><label>Correction of prior performance ID (optional)<input name="correctionOf" maxlength="80"></label><p>Uses the bodyweight and reference-category snapshot from your current profile. Report only a performance you actually completed. Drafts cannot qualify; estimates require exercise-specific approval.</p><fieldset><legend>MONTE Standard · self-reported attestation</legend><p id="rulebook-label"></p><div class="standard-checks" id="performance-checks"></div></fieldset><button class="button" type="submit">Validate and submit</button></form>'''
evidence='''<form id="evidence-form"><h3>3. Request evidence review</h3><label>Performance<select id="evidence-performance" required></select></label><label>Private MP4 · maximum 20 MiB<input id="evidence-file" type="file" accept="video/mp4" required></label><p>Continuous footage, complete movement, visible load and context. Only you and authorized reviewers can access uploaded evidence. Uploading is not approval. Evidence is separate from public exercise-library videos. <a href="/methodology/#privacy">Retention and access policy ↗</a></p><button class="button" type="submit">Submit private evidence</button></form><form id="reassessment-form"><h3>Reassess under the currently published methodology</h3><label>Performance ID<input name="performanceId" maxlength="80" required></label><label>Reason<input name="reason" maxlength="1000" required></label><p>Creates a separate result; original measurements and methodology versions remain unchanged.</p><button class="button" type="submit">Append reassessment</button></form>'''
workspace='''<section class="account-panel"><h2>Your performance. Your records.</h2><p>Private ranking requires the operator’s configured sign-in and an enrolled athlete identity. It is not activated in the public preview. No account is created by joining the waitlist.</p><button class="button" id="connect-ranking" type="button">Load my ranking workspace</button><p id="strength-status" role="status" aria-live="polite"></p><a id="admin-link" href="/strength/admin/" hidden>Authorized review tools ↗</a></section><section id="account-workspace" hidden><p id="identity-label"></p>'''+profile+performance+evidence+'<section class="strength-section"><h2>Performance &amp; calculation history</h2><p>Model changes, reviews, replacements and profile scenarios remain separate records. Current cards require the active model and current profile revision.</p><div id="performance-history"></div><h2>Evidence decisions</h2><div id="review-history"></div></section></section>'
bottom='<section class="strength-section"><h2>Nine ranks. No free promotions.</h2>'+gallery+'<p>Debitan is earned too. These are rank identities, not awarded achievements. No overall rank, average rank or combined score is calculated. Verification adds no bonus strength points.</p><p><strong>NO SHORTCUTS. NO FREE RANKS. EVERY RANK IS EARNED.</strong></p></section>'
method=f'<section class="strength-hero">{brand}<h1>Transparent standards.<br><em>Defensible achievements.</em></h1><p>MONTE WO Strength Index™ · MONTE Standard · MONTE Climb Scale · MONTE Verified · Discipline Rank</p>{notice}{links}</section>'
method+='''<section class="strength-section"><h2>What earns a rank?</h2><p>A valid performance must satisfy the approved standard for its own discipline, bodyweight and supported reference category. Attendance, streaks, account age, referrals, popularity and administrator preference cannot change strength eligibility. Ranks describe a performance achievement, never a person’s worth.</p><h2>Methodology status</h2><p>There are no approved threshold tables in this release. Squat, Bench Press, Deadlift and Strict Biceps Curl each have a separate empty draft table. No universal bodyweight exponent, competitor threshold or percentile-to-rank mapping has been adopted.</p><p>The implemented engine supports discipline-specific bodyweight lookup curves with exact piecewise-linear interpolation within approved bounds and separate age/sex categories. This is a computational format, not a validated scientific model. The curve shape, categories, nine thresholds and any permitted estimator must be calibrated and approved before use.</p><h2>Tested versus estimated</h2><p>A tested single records the load actually completed; it does not prove that the load was a true maximum. An estimated one-rep maximum predicts capacity from a multi-repetition set. The engine can support Epley, load × (1 + reps / 30), only when a specific methodology explicitly approves its repetition range for that discipline. No launch discipline currently approves estimated rank eligibility. No extrapolation beyond an approved range.</p><h2>Provisional is not MONTE Verified</h2><p>Provisional means self-reported eligibility under approved standards. MONTE Verified requires authorized evidence review under the matching MONTE Standard. You cannot approve your own performance. Verification never grants bonus points or a rank that the performance has not earned.</p><p>The draft policy proposes mandatory review from Titan upward; this is an evidence-control decision, not a calibrated strength threshold. It also remains subject to release approval.</p><h2>MONTE Climb Scale</h2><p>No official percentage is displayed for draft models. With an approved lookup model, the scale measures the interval between the current and next performance requirement. Display percentages are floored, never rounded up; 99% is not the next rank. The next standard and all validity/review requirements must be satisfied. Percentages are not comparable across disciplines.</p><h2>How a methodology is approved</h2><ol><li>Define the target population, exercise variation, equipment, evidence rules and rank meanings before analyzing outcomes.</li><li>Document licensed data, deduplication, missing values and representation. Competition entrants do not represent all gym users or beginners.</li><li>Compare absolute-load strata, ratio normalization, fitted allometry and conditional bodyweight curves on held-out athletes. Check bodyweight residuals, age/sex calibration, uncertainty, extreme sizes and sparse categories.</li><li>Choose and justify nine separate discipline thresholds. Validate external performance and reviewer agreement; collect new data where evidence is insufficient, especially strict curl and novice populations.</li><li>Obtain independent domain and statistical review. A different authorized publisher must approve the immutable version, and a release operator must allowlist its exact digest. Empty drafts and test fixtures cannot publish.</li></ol><h2>Sources consulted—not MONTE WO validation</h2><ul><li><a href="https://openpowerlifting.gitlab.io/opl-csv/" target="_blank" rel="noopener">OpenPowerlifting data service</a>: candidate competition dataset for squat, bench and deadlift, not a validated general-population ranking table.</li><li><a href="https://www.powerlifting.sport/rules/codes/info/technical-rules" target="_blank" rel="noopener">IPF technical rulebook</a>: judging reference; MONTE WO’s draft scope is not IPF certification.</li><li><a href="https://pubmed.ncbi.nlm.nih.gov/42191904/" target="_blank" rel="noopener">Fahey, 2026: sex-specific allometric normalization</a>: within-sample findings do not validate MONTE WO or its thresholds.</li><li><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC3761544/" target="_blank" rel="noopener">Submaximal RPE and predicted 1RM</a>: not approval of Epley or our wall-strict curl variation.</li></ul><p>This page documents the bundled draft versions. If a live methodology has since been published, its exact current version appears in the published-methodology register below.</p><p>See the source package’s methodology and calibration protocol for the evidence review, known limitations and release checklist. No full calibration dataset has been analyzed in this implementation.</p></section>'''
for r in catalog['rulebooks']:
 method+=f'<section class="strength-section rulebook" id="{r["discipline"]}"><span class="eyebrow">MONTE STANDARD · {r["id"]}</span><h2>{esc(r["title"])}</h2><small>DRAFT — NOT OFFICIAL · variation: {r["variation"]}</small><ol>'+''.join(f'<li><strong>{esc(c["id"].title())}.</strong> {esc(c["text"])}</li>' for c in r['checks'])+f'</ol><h3>Evidence and judging</h3><p>{esc(r["evidence"])}</p><p>{esc(r["visualExamples"])}</p><h3>Safety comes first</h3><p>{esc(r["safety"])}</p></section>'
method+='''<section class="strength-section" id="privacy"><h2>Private evidence, retention and history</h2><p>Only a provisioned athlete and authorized reviewers/administrators can access their evidence through authenticated server routes. Evidence is not stored in the public workout-media bucket, embedded in a public profile, cached by the service worker, or published to a leaderboard. The pilot accepts MP4 files up to 20 MiB and records their SHA-256 digest.</p><p>Evidence is held while review, appeal or the associated verified achievement needs it. No automatic retention duration is represented as active. A documented retention period, deletion/export procedure and private-bucket operational review must be completed before public enrollment. Contact Montewo@vitaflexbusinessgroup.com for requests; this preview does not promise automatic server deletion.</p><p>Performance, profile revisions, decisions, calculations and audit events are append-only through the application. Corrections create replacement records; a methodology update never silently rewrites a historical result. A profile change creates hypothetical eligibility scenarios, not fresh performance evidence. Current cards require the active model and current profile revision; historical achievements retain their original context.</p><p>No legal or security-framework compliance certification is claimed. Numerical limits and the 200-submission pilot cap are software guardrails, not athletic standards.</p></section>'''
admin=f'<section class="strength-hero">{brand}<h1>Review the evidence.<br><em>Protect the standard.</em></h1><p>Authorized MONTE WO review and governance workspace.</p>{notice}{links}</section><div class="account-panel"><p>No rank-award dropdown. Every decision must follow performance rules and retain its history. Your own evidence cannot be self-approved.</p><button class="button" type="button" id="connect-admin">Load authorized workspace</button><p id="strength-status" role="status"></p></div>'
admin+='''<section id="admin-workspace" hidden><section class="strength-section"><h2>Evidence review queue</h2><div id="review-queue"></div></section><section id="governance" hidden class="strength-section"><h2>Version governance</h2><p class="admin-warning">Models and rulebooks are immutable versions. Approval needs a different administrator and a separately allowlisted digest. Test fixtures, empty thresholds and unreviewed methodology cannot be published.</p><form id="draft-form"><h3>Create a new draft version</h3><label>Document type<select name="kind"><option value="models">Methodology / threshold table</option><option value="rulebooks">MONTE Standard rulebook</option></select></label><label>Version document (JSON)<textarea name="document" rows="12" required></textarea></label><label>Reason<input name="reason" maxlength="1000" required></label><button class="button" type="submit">Save immutable draft</button></form><form id="publish-form"><h3>Publish an independently approved version</h3><label>Document type<select name="kind"><option value="models">Methodology / threshold table</option><option value="rulebooks">MONTE Standard rulebook</option></select></label><label>Version ID<input name="versionId" required></label><label>Exact SHA-256 digest<input name="digest" required pattern="[a-f0-9]{64}"></label><label>Approval reason / review record<input name="reason" maxlength="1000" required></label><button class="button" type="submit">Request controlled publication</button></form><details><summary>Version register &amp; publication history</summary><pre id="standards-register"></pre></details><details><summary>Audit log (latest 500 events)</summary><pre id="audit-register"></pre></details></section></section>'''
def save(route,title,body):
 path=PUB/route;path.mkdir(parents=True,exist_ok=True)
 doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#090c13"><title>{esc(title)} | MONTE WO</title><meta name="description" content="MONTE WO Strength Index. Four independent disciplines. Every rank earned. Draft standards, not official rankings."><link rel="icon" href="/assets/icon-32.png"><link rel="manifest" href="/manifest.json"><link rel="stylesheet" href="/fonts.css"><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/launch.css"><link rel="stylesheet" href="/strength.css"><script src="/site.js" type="module"></script><script src="/strength.js" type="module"></script></head><body class="strength-page">{header}<main class="wrap" id="main">{body}</main>{footer}<script type="application/json" id="strength-catalog">{json.dumps(catalog,ensure_ascii=False).replace('<','&lt;')}</script></body></html>'''
 (path/'index.html').write_text(doc)
save('strength','MONTE WO Strength Index™',hero+cards+workspace+bottom)
save('methodology','MONTE Standard and methodology',method)
save('strength/admin','Authorized review and governance',admin)
save('strength-ranks','Nine earned Discipline Ranks',hero+bottom+'<section class="strength-section"><h2>Independent by design</h2><p>Barbell Squat, Barbell Bench Press, Barbell Deadlift and Strict Biceps Curl are assessed independently. No overall rank. No automatic Debitan award. Read the methodology before submitting a performance.</p></section>'+cards)
print('Generated Strength Index, four independent draft cards, methodology/rulebooks and authorized administration.')
